    {
        ArgumentNullException.ThrowIfNull(parameters);
        return _transport.UploadAsync<CardExpiry>(HttpMethod.Post, "/v2/cards/expiry", parameters, Envelope.Object, true, options, cancellationToken);
    }

    /// <summary>
    /// Check a card number: <c>POST /v2/cards/check</c>.
    /// <para>Checks a typed card number, for example from a checkout form: the Luhn checksum, a length that fits the network, the expiry when sent, and the BIN record. Accept the card when <c>scheme_valid</c> is true and <c>expired</c> is not. Only the first six and last four digits come back; nothing is stored.</para>
