/// <summary>The <c>bin</c> APIs: Look up a BIN.</summary>
public sealed class BinResource
{
    private readonly HttpTransport _transport;

    internal BinResource(HttpTransport transport)
    {
        _transport = transport;
    }

    /// <summary>
    /// Look up a BIN: <c>GET /v2/bin/{digits}</c>.
    /// <para>Looks up the first 6 to 8 digits of a card: network, type, level, funding, issuer, country with its flag, currency, and the issuer's record in the bank directory. Fewer than 6 digits answer <c>400 bin_too_short</c>; a BIN not in the tables <c>404 bin_not_found</c>.</para>
    /// <para>Price: 0.002 credits per successful call.</para>
    /// </summary>
    /// <param name="digits">The first 6 to 8 digits of the card number.</param>
    /// <param name="options">This call's timeout, retries and extra headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer, with <see cref="ApiResult.LastResponse"/>.</returns>
    /// <exception cref="ApiException">The API answered with an error; the subclass says which (<see cref="InsufficientCreditsException"/> when the credits ran out). Nothing was charged.</exception>
    /// <exception cref="ApiConnectionException">No answer: the API could not be reached, the connection failed, or the call timed out (<see cref="ApiTimeoutException"/>).</exception>
    public Task<BinRecord> LookupAsync(string digits, RequestOptions? options = null, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrEmpty(digits);
        return _transport.QueryAsync<BinRecord>(HttpMethod.Get, $"/v2/bin/{Uri.EscapeDataString(digits)}", null, Envelope.Object, options, cancellationToken);
    }
}
